export type PageBrandIconId = (typeof PAGE_BRAND_ICONS)[number]['value'];

export const PAGE_BRAND_ICON_IDS: readonly PageBrandIconId[] = PAGE_BRAND_ICONS.map(
  (icon) => icon.value,
);

const BRAND_ID_SET = new Set<string>(PAGE_BRAND_ICON_IDS);
const BRAND_BY_ID = new Map(PAGE_BRAND_ICONS.map((icon) => [icon.value, icon]));

export function isPageBrandIconId(value: string): value is PageBrandIconId {
  return BRAND_ID_SET.has(value);
}

export function getPageBrandIcon(value: string) {
  return BRAND_BY_ID.get(value as PageBrandIconId);
}
